-- QS World University Rankings 2027 for the listed catalogue.
--
-- QS published the 2027 edition on 18 June 2026. Each rank was looked up on
-- 8 October 2026 and is stored with the exact page that shows it, as an
-- unverified_sample source like the earlier QS profile import. Universities QS
-- does not rank get no row; the UI says "Not ranked by QS" rather than
-- inventing a position.
--
-- rank_sort is new: the catalogue lists universities by QS position, and a
-- band such as 601-610 sorts by its lower bound. rank_display keeps the
-- published notation.

begin;

alter table public.rankings add column rank_sort integer check (rank_sort > 0);
comment on column public.rankings.rank_sort is 'Numeric position for ordering; a published band sorts by its lower bound.';
create unique index rankings_university_label_year_key on public.rankings (university_id, label, year);


commit;
